let staffNote='',staffNoteContext=null,staffExpandedRoles=new Set();
function staffUiText(value){return String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function staffFace(person){return typeof StaffPortraits==='undefined'?'':StaffPortraits.html(person);}
function staffMoney(value){return '£'+Number(value).toLocaleString('en-GB');}
function staffEffect(candidate){return candidate.role==='MED'?'회복 훈련 체력 +'+candidate.recoveryBonus+' 추가 · 경기 부상 확률 '+Math.round((1-candidate.injuryMultiplier)*100)+'% 감소':'해당 포지션 기술 훈련 +1 추가 · 능력 훈련 체력 소모 '+candidate.energySaving+' 감소';}
function staffExpiry(value){let year=1,remaining=value;while(year<=season.year+1){const count=S.roundCountForYear(season,year);if(remaining<=count)return year+'시즌 '+remaining+'R 종료';remaining-=count;year++;}return season.year+'시즌 이후';}
function renderStaff(){
 const panel=$('staff-panel');if(!panel||typeof Staff==='undefined'||view!=='squad'||typeof squadTab!=='undefined'&&squadTab!=='health')return;
 for(const details of panel.querySelectorAll('[data-staff-role]')){if(details.open)staffExpandedRoles.add(details.dataset.staffRole);else staffExpandedRoles.delete(details.dataset.staffRole);}
 if(staffNoteContext&&(staffNoteContext.year!==season.year||staffNoteContext.round!==season.round))staffNote='';
 const candidates=Staff.candidates(season),contracts=Staff.roles.map(role=>Staff.active(season,role)).filter(Boolean),prep=season.competition==='league'&&season.match?.phase==='prep'&&season.match.minute===0;
 const cards=Staff.roles.map(role=>{
  const current=Staff.active(season,role),label=Staff.roleLabels[role],offers=candidates.filter(person=>person.role===role);
  if(current){
   const renewal=Staff.quote(season,'renew',role),release=Staff.quote(season,'release',role);
   return '<article class="staff-card contracted"><div class="staff-role"><span>'+role+'</span><h3>'+label+'</h3><b>계약 중</b></div><details class="staff-details" data-staff-role="'+role+'" '+(staffExpandedRoles.has(role)?'open':'')+'><summary>'+staffFace(current)+'<strong>'+staffUiText(current.name)+'</strong><span>남은 '+current.remaining+'경기 · 주급 '+staffMoney(current.wage)+'</span></summary><p class="staff-effect">'+staffEffect(current)+'</p><dl class="staff-terms"><div><dt>리그 경기마다</dt><dd>'+staffMoney(current.wage)+'</dd></div><div><dt>남은 계약</dt><dd>'+current.remaining+'경기</dd></div></dl><p class="staff-expiry '+(current.remaining<=2?'soon':'')+'">'+staffExpiry(current.expires)+'까지'+(current.trainingFrom>S.calendarClock(season,season.year,season.round)?' · 훈련 효과는 다음 주부터':'')+'</p><div class="staff-actions"><button type="button" class="secondary" data-staff-action="renew" data-staff-choice="'+role+'" '+(renewal.available?'':'disabled')+' aria-label="'+label+' '+staffUiText(current.name)+' 계약 7경기 연장, '+staffMoney(renewal.cost)+'">7경기 연장 · '+staffMoney(renewal.cost)+'</button><button type="button" class="staff-release" data-staff-action="release" data-staff-choice="'+role+'" '+(release.available?'':'disabled')+' aria-label="'+label+' '+staffUiText(current.name)+' 해지, 위약금 '+staffMoney(release.cost)+'">해지 · '+staffMoney(release.cost)+'</button></div><small class="staff-reason">'+staffUiText(renewal.reason||'연장 뒤 '+renewal.remaining+'경기 · 해지 위약금은 주급 1회분')+'</small></details></article>';
  }
  return '<article class="staff-card"><div class="staff-role"><span>'+role+'</span><h3>'+label+'</h3><b>공석</b></div><details class="staff-details" data-staff-role="'+role+'" '+(staffExpandedRoles.has(role)?'open':'')+'><summary><span class="staff-face-pair">'+offers.map(staffFace).join('')+'</span><strong>코치 후보 2명 보기</strong><span>계약금 '+staffMoney(offers[0].fee)+'부터 · 7경기 계약</span></summary><div class="staff-offers">'+offers.map(candidate=>{const q=Staff.quote(season,'hire',candidate.id);return '<div class="staff-offer"><div>'+staffFace(candidate)+'<strong>'+staffUiText(candidate.name)+'</strong><span>'+(candidate.tier===2?'수석 코치':'코치')+' · 7경기 계약</span></div><p class="staff-effect">'+staffEffect(candidate)+'</p><p class="staff-offer-cost">주급 '+staffMoney(candidate.wage)+' · 7경기 총 '+staffMoney(candidate.fee+candidate.wage*7)+'</p><button type="button" class="secondary" data-staff-action="hire" data-staff-choice="'+candidate.id+'" '+(q.available?'':'disabled')+' aria-label="'+label+' '+staffUiText(candidate.name)+' 영입, 계약금 '+staffMoney(candidate.fee)+'">영입 · 계약금 '+staffMoney(candidate.fee)+'</button><small class="staff-reason">'+staffUiText(q.reason||'계약금 즉시 차감 · 주급은 리그 결과 확정 때 차감')+'</small></div>';}).join('')+'</div></details></article>';
 }).join('');
 panel.innerHTML='<section class="staff-centre" aria-labelledby="staff-heading"><header class="staff-heading"><div><span class="eyebrow">COACHING TEAM</span><h2 id="staff-heading">코치 계약</h2><p>포지션별 코치와 의무 코치로 성장과 회복을 계획하세요.</p></div><span class="staff-count">'+contracts.length+' / 5명 계약</span></header><div class="staff-summary"><div><span>현재 구단 자금</span><strong>'+staffMoney(season.finance.balance)+'</strong></div><div><span>코치 리그 주급</span><strong>'+staffMoney(Staff.wages(season))+'</strong></div><div><span>의무 코치 효과</span><strong>'+Math.round((1-Staff.medicalModifier(season))*100)+'% 부상 확률 감소</strong></div></div><p class="staff-rules">'+(prep?'계약 관리 가능 · 역할마다 주 1회 변경':'다음 리그 경기 준비 때 계약 관리 가능')+' · 컵·챔피언스리그 경기에는 주급과 계약 기간이 소모되지 않습니다. 선수 성장 한계와 부상 휴식 기간을 지킵니다.</p>'+(staffNote?'<p class="staff-note" tabindex="-1" role="status">'+staffUiText(staffNote)+'</p>':'')+'<div class="staff-grid">'+cards+'</div></section>';
 panel.onclick=event=>{
  const button=event.target.closest('[data-staff-action]');if(!button||button.disabled)return;
  const operation=button.dataset.staffAction,choice=button.dataset.staffChoice;if(!['hire','renew','release'].includes(operation))return;
  action(()=>{const result=Staff[operation](season,choice);staffNoteContext={year:season.year,round:season.round};staffNote=result.name+' · '+({hire:'영입 완료',renew:'7경기 연장 완료',release:'계약 해지 완료'}[operation])+' · '+staffMoney(result.cost)+' 차감 · 잔액 '+staffMoney(season.finance.balance);});
  panel.querySelector('.staff-note')?.focus({preventScroll:true});
 };
}
